function readLocal(n,f=[]){try{return JSON.parse(fs.readFileSync(path.join(DATA_DIR,n),'utf8'))}catch{return f}}
function writeLocal(n,d){fs.writeFileSync(path.join(DATA_DIR,n),JSON.stringify(d,null,2),'utf8')}
const norm=s=>String(s||'').trim().replace(/\s+/g,' ');
const validPin=p=>/^\d{4}$/.test(String(p||''));
const validMobile=m=>/^\d{10}$/.test(String(m||''));
function validFullName(v){const s=norm(v);if(!/^[\p{L} ]+$/u.test(s))return false;const p=s.split(' ');return p.length>=2&&p.every(x=>[...x].length>=2)}
function studentPublic(x){return{id:x.id,name:x.name,fatherName:x.father_name??x.fatherName,mobile:x.mobile,pinSet:!!(x.pin_hash??x.pinHash)}}
function clampInt(v,min,max,def){const n=parseInt(v,10);return Number.isFinite(n)?Math.max(min,Math.min(max,n)):def}
function examPublic(x){return{id:Number(x.id),name:x.name,startAt:x.start_at??x.startAt??null,endAt:x.end_at??x.endAt??null,timerMode:x.timer_mode??x.timerMode??'none',durationMinutes:Number(x.duration_minutes??x.durationMinutes??0),perQuestionSeconds:Number(x.per_question_seconds??x.perQuestionSeconds??0),questionLimit:Number(x.question_limit??x.questionLimit??0),passingPercentage:Number(x.passing_percentage??x.passingPercentage??40),attemptLimit:Number(x.attempt_limit??x.attemptLimit??0),randomQuestions:!!(x.random_questions??x.randomQuestions),active:!!x.active,thumbnailUrl:(x.thumbnail_mime||x.thumbnailMime)?`/api/exams/${Number(x.id)}/thumbnail`:null}}
async function verifyStudent(mobile,pin){mobile=norm(mobile);if(!validMobile(mobile)||!validPin(pin))return null;if(useDb){const q=await pool.query('SELECT id,name,father_name,mobile,pin_hash FROM students WHERE mobile=$1',[mobile]);if(!q.rowCount||!q.rows[0].pin_hash)return null;return await bcrypt.compare(String(pin),q.rows[0].pin_hash)?q.rows[0]:null}const x=readLocal('students.json').find(s=>String(s.mobile)===mobile);if(!x||!x.pinHash)return null;return await bcrypt.compare(String(pin),x.pinHash)?x:null}
function nowStatus(e){const now=Date.now(),s=e.startAt?new Date(e.startAt).getTime():null,en=e.endAt?new Date(e.endAt).getTime():null;if(!e.active)return'inactive';if(s&&now<s)return'upcoming';if(en&&now>en)return'ended';return'available'}
function randomToken(){return crypto.randomBytes(24).toString('hex')}


const ADMIN_COOKIE='cie_admin_session';
const SESSION_TTL_MS=8*60*60*1000;
const SESSION_SECRET=process.env.ADMIN_SESSION_SECRET||crypto.randomBytes(32).toString('hex');
if(!process.env.ADMIN_SESSION_SECRET)console.warn('ADMIN_SESSION_SECRET is not set; admin sessions will reset on service restart.');
function parseCookies(req){const out={};String(req.headers.cookie||'').split(';').forEach(p=>{const i=p.indexOf('=');if(i>0)out[decodeURIComponent(p.slice(0,i).trim())]=decodeURIComponent(p.slice(i+1).trim())});return out}
function signAdminToken(adminId){const payload=Buffer.from(JSON.stringify({adminId,exp:Date.now()+SESSION_TTL_MS})).toString('base64url');const sig=crypto.createHmac('sha256',SESSION_SECRET).update(payload).digest('base64url');return payload+'.'+sig}
function verifyAdminToken(token){try{const [payload,sig]=String(token||'').split('.');if(!payload||!sig)return null;const expected=crypto.createHmac('sha256',SESSION_SECRET).update(payload).digest('base64url');if(sig.length!==expected.length||!crypto.timingSafeEqual(Buffer.from(sig),Buffer.from(expected)))return null;const obj=JSON.parse(Buffer.from(payload,'base64url').toString('utf8'));if(!obj.adminId||Date.now()>obj.exp)return null;return obj}catch{return null}}
function setAdminCookie(res,adminId){res.cookie(ADMIN_COOKIE,signAdminToken(adminId),{httpOnly:true,secure:process.env.NODE_ENV==='production',sameSite:'lax',maxAge:SESSION_TTL_MS,path:'/'})}
function clearAdminCookie(res){res.clearCookie(ADMIN_COOKIE,{path:'/'})}
function currentAdmin(req){return verifyAdminToken(parseCookies(req)[ADMIN_COOKIE])}
function requireAdmin(req,res,next){const a=currentAdmin(req);if(!a)return res.status(401).json({error:'Admin login required.'});req.admin=a;next()}
async function sendAdminResetEmail(to,resetUrl){const key=process.env.RESEND_API_KEY||'';const from=process.env.ADMIN_FROM_EMAIL||'CIE Exam <onboarding@resend.dev>';if(!key)throw new Error('Email recovery is not configured yet. Add RESEND_API_KEY in Render Environment.');const r=await fetch('https://api.resend.com/emails',{method:'POST',headers:{'Authorization':'Bearer '+key,'Content-Type':'application/json'},body:JSON.stringify({from,to,subject:'CIE Exam Admin Password Reset',html:`<p>A password reset was requested for the CIE Exam Admin Portal.</p><p><a href="${resetUrl}">Reset Admin Password</a></p><p>This link expires in 20 minutes. If you did not request this, ignore this email.</p>`})});if(!r.ok){const t=await r.text();throw new Error('Could not send reset email: '+t)}}

async function initDb(){if(!useDb)return;await pool.query(`
CREATE TABLE IF NOT EXISTS students(id BIGSERIAL PRIMARY KEY,name TEXT NOT NULL,father_name TEXT NOT NULL,mobile TEXT UNIQUE NOT NULL,created_at TIMESTAMPTZ DEFAULT NOW());
ALTER TABLE students ADD COLUMN IF NOT EXISTS pin_hash TEXT;
CREATE TABLE IF NOT EXISTS exams(
 id BIGSERIAL PRIMARY KEY,name TEXT NOT NULL,start_at TIMESTAMPTZ,end_at TIMESTAMPTZ,
 timer_mode TEXT NOT NULL DEFAULT 'none',duration_minutes INTEGER NOT NULL DEFAULT 0,
 per_question_seconds INTEGER NOT NULL DEFAULT 0,question_limit INTEGER NOT NULL DEFAULT 0,
 passing_percentage NUMERIC(5,2) NOT NULL DEFAULT 40,attempt_limit INTEGER NOT NULL DEFAULT 0,
 random_questions BOOLEAN NOT NULL DEFAULT FALSE,active BOOLEAN NOT NULL DEFAULT TRUE,created_at TIMESTAMPTZ DEFAULT NOW());
ALTER TABLE exams ADD COLUMN IF NOT EXISTS thumbnail_data BYTEA;
ALTER TABLE exams ADD COLUMN IF NOT EXISTS thumbnail_mime TEXT;
CREATE TABLE IF NOT EXISTS app_releases(
 id BIGSERIAL PRIMARY KEY,version TEXT NOT NULL,notes TEXT,apk_data BYTEA NOT NULL,apk_mime TEXT NOT NULL DEFAULT 'application/vnd.android.package-archive',
 file_name TEXT NOT NULL DEFAULT 'CIE_Online_Exam.apk',published BOOLEAN NOT NULL DEFAULT FALSE,created_at TIMESTAMPTZ DEFAULT NOW());
CREATE INDEX IF NOT EXISTS idx_app_releases_published ON app_releases(published,created_at DESC);
CREATE TABLE IF NOT EXISTS questions(id BIGSERIAL PRIMARY KEY,question TEXT NOT NULL,option_a TEXT NOT NULL,option_b TEXT NOT NULL,option_c TEXT NOT NULL,option_d TEXT NOT NULL,answer CHAR(1) NOT NULL);
ALTER TABLE questions ADD COLUMN IF NOT EXISTS exam_id BIGINT;
ALTER TABLE questions ADD COLUMN IF NOT EXISTS question_seconds INTEGER;
CREATE INDEX IF NOT EXISTS idx_questions_exam ON questions(exam_id,id);
CREATE TABLE IF NOT EXISTS results(id BIGSERIAL PRIMARY KEY,student_id BIGINT,name TEXT NOT NULL,father_name TEXT NOT NULL,mobile TEXT NOT NULL,score INTEGER NOT NULL,total INTEGER NOT NULL,percentage NUMERIC(6,2) NOT NULL,status TEXT NOT NULL,created_at TIMESTAMPTZ DEFAULT NOW());
ALTER TABLE results ADD COLUMN IF NOT EXISTS review_json JSONB;
ALTER TABLE results ADD COLUMN IF NOT EXISTS exam_id BIGINT;
ALTER TABLE results ADD COLUMN IF NOT EXISTS exam_name TEXT;
ALTER TABLE results DROP CONSTRAINT IF EXISTS results_mobile_key;
CREATE INDEX IF NOT EXISTS idx_results_mobile_created ON results(mobile,created_at DESC);
CREATE INDEX IF NOT EXISTS idx_results_exam_created ON results(exam_id,created_at DESC);
CREATE TABLE IF NOT EXISTS exam_sessions(
 id BIGSERIAL PRIMARY KEY,token TEXT UNIQUE NOT NULL,student_id BIGINT NOT NULL,exam_id BIGINT NOT NULL,
 started_at TIMESTAMPTZ DEFAULT NOW(),expires_at TIMESTAMPTZ,question_ids JSONB NOT NULL,submitted_at TIMESTAMPTZ);
CREATE INDEX IF NOT EXISTS idx_sessions_student_exam ON exam_sessions(student_id,exam_id,started_at DESC);
CREATE TABLE IF NOT EXISTS pin_reset_requests(id BIGSERIAL PRIMARY KEY,student_id BIGINT,mobile TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'PENDING',requested_at TIMESTAMPTZ DEFAULT NOW(),resolved_at TIMESTAMPTZ);
CREATE INDEX IF NOT EXISTS idx_pin_reset_status ON pin_reset_requests(status,requested_at DESC);
CREATE TABLE IF NOT EXISTS admins(
 id BIGSERIAL PRIMARY KEY,admin_id TEXT UNIQUE NOT NULL,name TEXT NOT NULL DEFAULT 'Administrator',email TEXT,
 password_hash TEXT NOT NULL,active BOOLEAN NOT NULL DEFAULT TRUE,created_at TIMESTAMPTZ DEFAULT NOW(),updated_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS admin_password_resets(
 id BIGSERIAL PRIMARY KEY,admin_id TEXT NOT NULL,token_hash TEXT UNIQUE NOT NULL,expires_at TIMESTAMPTZ NOT NULL,used_at TIMESTAMPTZ,created_at TIMESTAMPTZ DEFAULT NOW());
CREATE INDEX IF NOT EXISTS idx_admin_reset_token ON admin_password_resets(token_hash,expires_at);
CREATE TABLE IF NOT EXISTS promotions(
 id BIGSERIAL PRIMARY KEY,title TEXT NOT NULL,subtitle TEXT,details TEXT,link_text TEXT,link_url TEXT,
 active BOOLEAN NOT NULL DEFAULT TRUE,sort_order INTEGER NOT NULL DEFAULT 0,created_at TIMESTAMPTZ DEFAULT NOW(),updated_at TIMESTAMPTZ DEFAULT NOW());
`);
const envAdminId=norm(process.env.ADMIN_ID),envAdminPassword=String(process.env.ADMIN_PASSWORD||''),envAdminEmail=norm(process.env.ADMIN_EMAIL);
if(envAdminId&&envAdminPassword){const a=await pool.query('SELECT id,email FROM admins WHERE admin_id=$1',[envAdminId]);if(!a.rowCount){const ph=await bcrypt.hash(envAdminPassword,12);await pool.query('INSERT INTO admins(admin_id,name,email,password_hash) VALUES($1,$2,$3,$4)',[envAdminId,'Super Admin',envAdminEmail||null,ph]);console.log('Initial admin account created from Render environment.')}else if(envAdminEmail&&!a.rows[0].email){await pool.query('UPDATE admins SET email=$1,updated_at=NOW() WHERE admin_id=$2',[envAdminEmail,envAdminId])}}
const pc=await pool.query('SELECT COUNT(*)::int n FROM promotions');if(!pc.rows[0].n){await pool.query(`INSERT INTO promotions(title,subtitle,details,link_text,link_url,sort_order) VALUES
('Admissions Open','CIE Computer Courses','New batch admissions are open. Contact CIE for course and enrollment details.','Visit CIE','https://cie.co.in',1),
('CIE Online Contest','Learn • Compete • Grow','Participate in online tests through the CIE Exam App and view your result instantly.','View Exams','#upcoming-exams',2),
('Institute / Franchise Promotion','Grow with CIE','Use this promotion area for CIE announcements, admissions, contests and institute promotions.','','',3)`)}

const ex=await pool.query('SELECT id FROM exams ORDER BY id LIMIT 1');
let legacyId;
if(!ex.rowCount){legacyId=(await pool.query(`INSERT INTO exams(name,timer_mode,passing_percentage,attempt_limit,active) VALUES('Legacy / General Exam','none',40,0,true) RETURNING id`)).rows[0].id}else legacyId=ex.rows[0].id;
await pool.query('UPDATE questions SET exam_id=$1 WHERE exam_id IS NULL',[legacyId]);
}

