const ADMIN_LOGIN_HTML="<!doctype html><html><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>CIE Admin Login</title><style>body{margin:0;font-family:Arial;background:#f4f7fb;color:#172238}.box{max-width:430px;margin:70px auto;background:white;padding:28px;border-radius:18px;box-shadow:0 10px 32px #183b6b18}.logo{text-align:center;color:#0b4da2}label{display:block;margin-top:14px;font-weight:700}input{width:100%;box-sizing:border-box;padding:13px;border:1px solid #ccd7e5;border-radius:10px;margin-top:6px;font-size:16px}button{width:100%;padding:13px;border:0;border-radius:10px;background:#0b4da2;color:white;font-weight:700;margin-top:18px;cursor:pointer}.secondary{background:#5b6f87}.small{font-size:13px;color:#68758a;text-align:center;margin-top:14px}.link{color:#0b4da2;cursor:pointer;font-weight:700}.msg{margin-top:14px;padding:10px;border-radius:8px;background:#eef4fb;display:none}</style></head><body><div class=\"box\"><div class=\"logo\"><h1>CIE Admin Login</h1><p>Secure Exam Administration</p></div><div id=\"login\"><label>Admin ID<input id=\"adminId\" autocomplete=\"username\"></label><label>Password<input id=\"password\" type=\"password\" autocomplete=\"current-password\"></label><button id=\"loginBtn\">Login</button><div class=\"small\"><span class=\"link\" id=\"forgotLink\">Forgot Password?</span></div></div><div id=\"forgot\" style=\"display:none\"><h3>Forgot Password</h3><label>Admin ID<input id=\"fAdminId\"></label><label>Registered Email<input id=\"email\" type=\"email\"></label><button id=\"sendBtn\">Send Reset Link</button><button class=\"secondary\" id=\"backBtn\">Back to Login</button></div><div id=\"msg\" class=\"msg\"></div><div class=\"small\"><a href=\"/\" style=\"color:#0b4da2\">\u2190 Back to CIE Exam Portal</a></div></div><script>const $=x=>document.getElementById(x),msg=t=>{$('msg').textContent=t;$('msg').style.display='block'};$('loginBtn').onclick=async()=>{try{const r=await fetch('/api/admin/auth/login',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({adminId:$('adminId').value,password:$('password').value})});const j=await r.json();if(!r.ok)throw Error(j.error);location.href='/admin'}catch(e){msg(e.message)}};$('forgotLink').onclick=()=>{$('login').style.display='none';$('forgot').style.display='block';$('fAdminId').value=$('adminId').value};$('backBtn').onclick=()=>{$('forgot').style.display='none';$('login').style.display='block'};$('sendBtn').onclick=async()=>{try{const r=await fetch('/api/admin/auth/forgot',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({adminId:$('fAdminId').value,email:$('email').value})});const j=await r.json();if(!r.ok)throw Error(j.error);msg(j.message)}catch(e){msg(e.message)}};</script></body></html>";
const ADMIN_MEDIA_HTML="<!doctype html><html><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>CIE App & Exam Media</title><style>body{font-family:Arial;background:#f4f7fb;color:#172238;margin:0}.wrap{max-width:900px;margin:35px auto;padding:0 16px}.top{display:flex;justify-content:space-between;align-items:center;gap:12px}.card{background:#fff;padding:22px;border-radius:16px;box-shadow:0 6px 22px #17365d18;margin:18px 0}label{display:block;font-weight:700;margin-top:12px}input,select,textarea,button{width:100%;box-sizing:border-box;padding:12px;margin-top:7px;border-radius:9px;border:1px solid #ccd7e5}button{border:0;background:#0b4da2;color:#fff;font-weight:700;cursor:pointer}.green{background:#168a55}.danger{background:#b3261e}.row{display:grid;grid-template-columns:1fr 1fr;gap:12px}.msg{padding:10px;background:#eef4fb;border-radius:9px;margin-top:12px;display:none}.thumb{max-width:260px;max-height:150px;border-radius:10px;margin-top:10px}.small{font-size:13px;color:#68758a}a{color:#0b4da2;font-weight:700;text-decoration:none}@media(max-width:650px){.row{grid-template-columns:1fr}.top{display:block}}</style></head><body><div class=\"wrap\"><div class=\"top\"><div><h1>CIE App Management</h1><div class=\"small\">APK updates + Exam thumbnails</div></div><div><a href=\"/admin\">\u2190 Admin Portal</a></div></div><div class=\"card\"><h2>\ud83d\udcf1 Upload / Publish Android APK</h2><div id=\"current\" class=\"small\">Checking current published app\u2026</div><label>Version<input id=\"version\" placeholder=\"Example: V3.4\"></label><label>What's New / Update Notes<textarea id=\"notes\" rows=\"4\" placeholder=\"Write update details\"></textarea></label><label>Select APK<input id=\"apk\" type=\"file\" accept=\".apk,application/vnd.android.package-archive\"></label><button class=\"green\" id=\"uploadApk\">Upload & Publish APK</button><div id=\"apkMsg\" class=\"msg\"></div></div><div class=\"card\"><h2>\ud83d\uddbc Exam Thumbnail</h2><p class=\"small\">Create the exam normally, then select it here and upload its thumbnail. It will appear on the website and is also supplied to the Student App API.</p><label>Select Exam<select id=\"exam\"></select></label><div id=\"preview\"></div><label>Select Thumbnail<div class=\"small\" style=\"margin-top:6px;font-weight:400\"><b>Recommended / Required Thumbnail Size: 1200 × 675 px (16:9)</b><br>Format: JPG, PNG or WebP &nbsp;•&nbsp; Maximum file size: 5 MB</div><input id=\"thumb\" type=\"file\" accept=\"image/jpeg,image/png,image/webp\"></label><div class=\"row\"><button id=\"uploadThumb\">Upload / Replace Thumbnail</button><button class=\"danger\" id=\"removeThumb\">Remove Thumbnail</button></div><div id=\"thumbMsg\" class=\"msg\"></div></div></div><script>const $=x=>document.getElementById(x);function show(id,t){$(id).textContent=t;$(id).style.display='block'}async function loadApp(){try{const r=await fetch('/api/public/app-info'),j=await r.json();$('current').textContent=j.available?'Published: '+j.version+(j.notes?' \u2022 '+j.notes:''):'No APK published yet.'}catch{$('current').textContent='Could not load app status.'}}async function loadExams(){const r=await fetch('/api/admin/exams'),j=await r.json();$('exam').innerHTML=j.map(x=>'<option value=\"'+x.id+'\">'+String(x.name).replace(/</g,'&lt;')+'</option>').join('');preview()}function preview(){const id=$('exam').value;$('preview').innerHTML=id?'<img class=\"thumb\" src=\"/api/exams/'+id+'/thumbnail?t='+Date.now()+'\" onerror=\"this.remove()\">':''}$('exam').onchange=preview;$('uploadApk').onclick=async()=>{const f=$('apk').files[0],v=$('version').value.trim();if(!f||!v)return show('apkMsg','Version and APK are required.');const fd=new FormData();fd.append('apk',f);fd.append('version',v);fd.append('notes',$('notes').value);show('apkMsg','Uploading\u2026 please wait.');try{const r=await fetch('/api/admin/app-release',{method:'POST',body:fd}),j=await r.json();if(!r.ok)throw Error(j.error);show('apkMsg','APK uploaded and published successfully.');loadApp()}catch(e){show('apkMsg',e.message)}};$('uploadThumb').onclick=async()=>{const f=$('thumb').files[0],id=$('exam').value;if(!id||!f)return show('thumbMsg','Select exam and image.');const fd=new FormData();fd.append('thumbnail',f);try{const r=await fetch('/api/admin/exams/'+id+'/thumbnail',{method:'POST',body:fd}),j=await r.json();if(!r.ok)throw Error(j.error);show('thumbMsg','Thumbnail uploaded successfully.');preview()}catch(e){show('thumbMsg',e.message)}};$('removeThumb').onclick=async()=>{const id=$('exam').value;if(!id)return;try{const r=await fetch('/api/admin/exams/'+id+'/thumbnail',{method:'DELETE'}),j=await r.json();if(!r.ok)throw Error(j.error);show('thumbMsg','Thumbnail removed.');preview()}catch(e){show('thumbMsg',e.message)}};loadApp();loadExams();</script></body></html>";
const ADMIN_RESET_HTML="<!doctype html><html><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>Reset CIE Admin Password</title><style>body{font-family:Arial;background:#f4f7fb}.box{max-width:430px;margin:80px auto;background:#fff;padding:28px;border-radius:18px}input,button{width:100%;box-sizing:border-box;padding:13px;margin-top:12px;border-radius:10px}input{border:1px solid #ccd7e5}button{border:0;background:#0b4da2;color:#fff;font-weight:bold}.msg{margin-top:14px}</style></head><body><div class=\"box\"><h2>Reset Admin Password</h2><p>Enter a new password of at least 8 characters.</p><input id=\"p1\" type=\"password\" placeholder=\"New Password\"><input id=\"p2\" type=\"password\" placeholder=\"Confirm New Password\"><button id=\"go\">Reset Password</button><div id=\"msg\" class=\"msg\"></div></div><script>document.getElementById('go').onclick=async()=>{const p1=document.getElementById('p1').value,p2=document.getElementById('p2').value,m=document.getElementById('msg');if(p1!==p2){m.textContent='Passwords do not match.';return}const token=new URLSearchParams(location.search).get('token')||'';try{const r=await fetch('/api/admin/auth/reset',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({token,newPassword:p1})});const j=await r.json();if(!r.ok)throw Error(j.error);m.innerHTML='Password updated. <a href=\"/admin\">Login now</a>'}catch(e){m.textContent=e.message}};</script></body></html>";

function serveAdminPage(req,res,file){if(!currentAdmin(req))return res.redirect('/admin');const f=path.join(__dirname,'admin',file);if(!fs.existsSync(f))return res.status(404).send('<h2>Admin page not found.</h2>');return res.type('html').send(fs.readFileSync(f,'utf8'))}
